export const isAgendaAppointmentViewModel = appointmentViewModel => "isAgendaModel" in appointmentViewModel;
export const isCollectorViewModel = appointmentViewModel => "isCompact" in appointmentViewModel;
export const isGridAppointmentViewModel = appointmentViewModel => !isAgendaAppointmentViewModel(appointmentViewModel) && !isCollectorViewModel(appointmentViewModel);
